import{_ as a,o,c,a2 as r}from"./chunks/framework.CiKk3sJz.js";const p=JSON.parse('{"title":"漫画 · 第 22 话 容器查询：组件不问屏幕，只问容器","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.22-container-queries.md","filePath":"comics/css/EP.22-container-queries.md","lastUpdated":1792579602000}'),t={name:"comics/css/EP.22-container-queries.md"};function i(n,e,d,s,l,h){return o(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-22-话-容器查询-组件不问屏幕-只问容器" tabindex="-1">漫画 · 第 22 话 容器查询：组件不问屏幕，只问容器 <a class="header-anchor" href="#漫画-·-第-22-话-容器查询-组件不问屏幕-只问容器" aria-label="Permalink to &quot;漫画 · 第 22 话 容器查询：组件不问屏幕，只问容器&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/12-container-queries">docs/css/12-container-queries.md</a> ｜ 原画：<a href="./EP.22-container-queries.svg">EP.22-container-queries.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。同一张卡片在侧栏被挤爆、在主区却正常，气得跳脚——媒体查询只看屏幕宽度，不管组件实际多宽。</li><li><strong>标签君</strong>：HTML5 结构师，搬出&quot;container-type + @container&quot;组合拳，让组件自带断点，消费者零媒体查询。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>响应式章（EP.05）讲了媒体查询管设备、clamp 管流式排版，但组件级响应还有最后一块拼图：容器查询。像素酱先被&quot;同一张卡片两种命运&quot;折磨，再学会 <code>container: card / inline-size</code> 声明容器、用 <code>@container card (min-width: 400px)</code> 写组件断点，最后用 <code>cqi</code> 单位让标题字号随容器宽度平滑缩放。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>侧栏 240px 里的卡片被 <code>@media (min-width: 768px)</code> 强制横排——屏幕够宽，但卡片实际只有 240px，文字挤成一团。主区 720px 里的同一张卡片横排正常。媒体查询的盲区：它只看视口，不看组件容器。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>container: card / inline-size</code> 把包裹元素变成尺寸容器；<code>@container card (min-width: 400px)</code> 让后代元素查询容器而非视口。命名容器防止嵌套时外层干扰内层。<code>cqi/cqw/cqh</code> 单位让组件内元素随容器宽度缩放，比 <code>clamp()</code> 的 <code>vw</code> 更精准。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>同一段 HTML，放进 320px 容器自动竖排，放进 720px 容器自动横排。卡片组件自带断点，页面消费者只需 <code>&lt;div class=&quot;card-wrapper&quot;&gt;</code> 包裹，无需再写媒体查询。设计系统的复用成本断崖式下降。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>container-type</code> 写在包裹容器上，不是组件根元素——否则尺寸计算会递归。</li><li>给容器命名：<code>container: card / inline-size</code>，防止嵌套时外层干扰内层。</li><li>容器单位 <code>cqi/cqw</code> 按容器宽度缩放，比 <code>clamp()</code> 的 <code>vw</code> 更精准——它缩放的是容器不是视口。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么容器查询不能直接把 <code>container-type</code> 写在卡片组件的根元素上？</p><p><strong>答</strong>：<code>container-type</code> 需要容器有明确的尺寸来源。如果写在组件根元素上，组件的尺寸由内容撑开，而内容又依赖 <code>@container</code> 查询的结果——形成循环依赖。正确做法是把 <code>container-type</code> 写在<strong>包裹组件的父容器</strong>上，让父容器提供稳定的尺寸基准。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>卡片组件自适应 + 嵌套容器 + 容器单位 + 导航栏自适应：<a href="./../../examples/css/12-container-queries/index-01-container-queries.html">examples/css/12-container-queries/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 23 话《层叠层》——<code>@layer</code> 显式分层，终结 <code>!important</code> 战争与特异性军备竞赛。</p>',22)])])}const q=a(t,[["render",i]]);export{p as __pageData,q as default};
